@js:(function(){
 var h = '' + result;
 var out = [];
 var bn = '';
 try { if (book) { bn = '' + book.name; } } catch (e) { bn = ''; }
 function cleanTitle(t) {
 t = '' + t;
 if (t.indexOf('\u9605\u8bfb\u6587\u7ae0') === 0) {
 t = t.replace(/^(\u9605\u8bfb\u6587\u7ae0|\u5b8c\u7ed3|\u6536\u85cf\u5230\u4e66\u67dc|\u6700\u65b0\u7ae0\u8282|\u5168\u6587\u9605\u8bfb|\u514d\u8d39\u9605\u8bfb|\u65e0\u5f39\u7a97|\s)+/, '');
 if (bn !== '' && t.indexOf(bn) === 0) { t = t.substring(bn.length); }
 }
 t = t.replace(/^[\s\u200b-\u200f\u2060\ufeff]+/, '');
 t = t.replace(/[\s\u200b-\u200f\u2060\ufeff]+$/, '');
 return t;
 }
 var re = /<li[^>]*data-id="\d+"[\s\S]*?<\/li>/g;
 var m;
 while ((m = re.exec(h)) !== null) {
 var attrs = m[0].match(/data-[A-Za-z0-9_-]+="[^"]*"/g);
 if (!attrs) { continue; }
 var ord = -1;
 var url = '';
 var name = '';
 for (var i = 0; i < attrs.length; i++) {
 var s = attrs[i];
 var p = s.indexOf('=');
 var k = s.substring(5, p);
 var v = s.substring(p + 2, s.length - 1);
 if (k === 'id') { continue; }
 if (/^\d+$/.test(v)) { if (ord < 0) { ord = parseInt(v, 10); } continue; }
 if (url === '') {
 var dec = '';
 try { dec = '' + java.base64Decode(v); } catch (e) { dec = ''; }
 if (dec.charAt(0) === '/') { if (/\.html$/.test(dec)) { url = dec; continue; } }
 }
 if (name === '') { name = v; }
 }
 if (url === '') { continue; }
 out.push({ ord: ord, title: cleanTitle(name), url: url });
 }
 out.sort(function(a, b){ return a.ord - b.ord; });
 var res = [];
 for (var j = 0; j < out.length; j++) { res.push({ title: out[j].title, url: out[j].url }); }
 return res;
})()

ruleToc.nextTocUrl:
@js:(function(){
 var h = '' + result;
 var m = /<a[^>]*href="([^"]+)"[^>]*id="end"/.exec(h);
 if (!m) { m = /<a[^>]*id="end"[^>]*href="([^"]+)"/.exec(h); }
 if (!m) { return []; }
 var n = /(\d+)\.html/.exec(m[1]);
 if (!n) { return []; }
 var last = parseInt(n[1], 10);
 var cur = 1;
 var bm = /catalog\/(\d+)\.html/.exec('' + baseUrl);
 if (bm) { cur = parseInt(bm[1], 10); }
 var t = '' + book.tocUrl;
 var pages = [];
 for (var i = cur + 1; i <= last; i++) { pages.push(t + i + '.html'); }
 return pages;
})()
